// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log log;

    function setUp() public {
        log = new Log();
        c = new C(address(log));
    }

    function testFuzz_property(uint256 amount) public {
        // 1. Admissible domain: positive amount within a reasonable range
        vm.assume(amount > 0 && amount <= 1000 ether);

        // 2. Deploy adversarial re-entrant attacker
        ReEntrantAttacker attacker = new ReEntrantAttacker();
        vm.deal(address(attacker), amount);

        // 3. Attacker calls Put, which triggers AddMessage -> attacker's fallback -> Put again
        uint256 balanceBefore = c.Acc(address(attacker)).balance;
        attacker.attack(address(c), amount);
        uint256 balanceAfter = c.Acc(address(attacker)).balance;

        // 4. Assert: after one external call to Put, the balance should equal the amount sent exactly once.
        //    Reference prevents re-entrancy, so balanceAfter == amount. Mutant allows re-entrancy, so
        //    balanceAfter > amount (inflated).
        assertTrue(balanceAfter == amount);
    }
}

contract ReEntrantAttacker {
    bool private reentered;
    C private target;
    uint256 private attackAmount;

    function attack(address _target, uint256 _amount) external payable {
        target = C(_target);
        attackAmount = _amount;
        target.Put{value: _amount}(0);
    }

    fallback() external payable {
        if (!reentered) {
            reentered = true;
            target.Put{value: 0}(0);
        }
    }
}

contract Log {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

