import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _unlockTime, uint256 _sendValue) public {
        // _sendValue must be at least 1 wei to observe balance changes
        vm.assume(_sendValue > 0);
        // deploy a malicious Log contract that re-enters c.Put() when AddMessage is called
        MaliciousLog badLog = new MaliciousLog(address(c));
        // create a user that will interact with c
        address user = makeAddr("user");
        // give the user enough ether to send and to pay for gas
        vm.deal(user, _sendValue * 10 + 1 ether);
        // record balance before the call
        uint256 balanceBefore = c.Acc(user).balance;
        // user calls Put via the malicious log (the adversary controls the log)
        vm.prank(user);
        c.Put{value: _sendValue}(_unlockTime);
        // after the call, read the actual balance
        uint256 balanceAfter = c.Acc(user).balance;
        // Property: the increase in balance must be exactly the sent value
        assertTrue(balanceAfter == balanceBefore + _sendValue);
    }
}

// Minimal adversarial helper: a Log contract that calls back into c.Put upon AddMessage
contract MaliciousLog {
    C public target;
    constructor(address _c) {
        target = C(_c);
    }
    function AddMessage(address, uint, string memory) external {
        // re-enter Put with the same msg.sender and a small amount (no value needed? msg.sender cannot send value from here)
        // The bug is that the mutant allows reentry, so the caller's balance is updated again inside AddMessage.
        // We call Put with 0 value; the original Put already has the value, so the reentry adds extra balance increase if possible.
        // To trigger extra balance increase we need value; but we cannot send value from this call.
        // Instead, the reentry simply calls Put again without value; the original balance increase already happened.
        // Actually, the reentry triggers another Put call which tries to call AddMessage again.
        // To cause real inflation we need a recursion that sends value inside the reentry, which from an external contract is impossible.
        // However, the reentrancy simply allows the caller to call Put again while locked=true in reference, but mutant has no lock.
        // The balance increase in Put is msg.value. A reentrant call without value adds 0, so no inflation.
        // The difference is that in mutant, reentry does not revert; in reference it does revert due to reentrancy guard.
        // The property we need to check is that Put does not revert when called from inside AddMessage? No, the original property is about balance.
        // We need a helper that can supply value when re-entering. An attacker contract can call Put and, from its receive or fallback, call Put again with value.
        // But here the reentry point is AddMessage, called during Put. To inflate balance, we need the reentry to send value. A contract can't send value it doesn't have during a call.
        // The simpler property: in reference, a reentrant call via a malicious Log fails; in mutant it succeeds. But the property must be about balance or revert.
        // Previous failed tries: using a reentrant caller's receive. The difference given: "after a call to Put(...) completes, the value of state variable Put differs: P.Put() != M.Put()." But Put is a function, not state variable. Probably means the state variable Acc[msg.sender].balance.
        // So we must prove balance inflation. We need a way to deliver value inside a reentrant call. That's impossible without the caller having a contract that forwards value.
        // The attacker could be a contract that calls Put and then, during AddMessage, calls Put again with its own balance? But inside AddMessage, the caller is the C contract itself, so msg.sender is the original user. The original user's balance is updated. The attacker can't force the original user to send more value.
        // Actually, the original user is an EOA in typical fuzzing, but we can make the user an attacker contract that holds Ether and can call Put with value when its fallback is triggered.
        // The reentrancy path: user (contract) calls Put{value: X}. Inside Put, it calls LogFile.AddMessage. If LogFile is a malicious contract, its AddMessage can call back into Put with another value Y, using the user's address as msg.sender? No, the call is from the malicious log, msg.sender would be the log, not the user. So the balance of the log would increase, not the user's.
        // To inflate user's balance, the reentrant call must be from the user's address. That can happen if during AddMessage, the log does some external call that triggers user's fallback, which then calls Put. But that requires the user to be a contract. So we need the user to be an attacker contract.
        // Revised: deploy an attacker contract that has ETH and a fallback which calls Put. The attacker calls Put; inside Put, C calls Log.AddMessage; if Log is malicious, it calls attacker's fallback by sending ETH or something; attacker's fallback calls Put again with value. This reenters Put and adds balance to attacker.
        // The difference: in reference, the nonReentrant modifier prevents reentry; in mutant it allows it.
        // So we need two helpers: Attacker (user) and MaliciousLog. Attacker calls Put, MaliciousLog calls back to Attacker, which reenters Put with value.
        // Then the property: balance of attacker after the single external invocation is greater than the original sent value.
        // So we fuzz the unlock time and the amount, and the extra amount in the second Put. The attacker will have enough ETH to send both.
        // The attack works only if during AddMessage, the log can trigger a call to the attacker that gives control back. How? AddMessage doesn't do any external call except writing to storage and emitting events. There's no .call or .transfer. So reentrancy cannot happen through Log if Log is standard.
        // However, the contract uses LogFile which is an external contract (Log). The Log contract's AddMessage is called. If Log is malicious, its AddMessage can do anything, including making an external call to an address provided as parameter (msg.sender?). But msg.sender in AddMessage is the C contract? No, in C, AddMessage is called as LogFile.AddMessage(msg.sender,msg.value,"Put"); So msg.sender inside AddMessage is the C contract's address (since C calls it). The first parameter _adr is the original user. So the malicious log can use _adr to call the original user if it trusts that parameter.
        // So: MaliciousLog.AddMessage(address _adr, uint, string memory) { _adr.call{value: 0}(""); } would trigger the fallback of _adr (the user contract). The user contract's fallback calls Put with some value. This sends value again, inflating balance.
        // That is allowed by the rules: the adversarial counterparty (MaliciousLog) is required; we can make the user a contract as well? The fuzzer gives an address; we can't assume it has code. So we must deploy the user contract (attacker) and use its address as the actor. But the fuzzer provides fuzzed parameters; we can deploy helpers and use them.
        // The rule says: "Driven through the public/external entry `Put`, P and M differ..." So we drive through Put from some caller. We can set the caller to be an attacker contract we deploy. That's allowed: we can use vm.prank(attacker) where attacker is a deployed contract.
        // So the test: deploy MaliciousLog (which will reenter via the user's fallback) and deploy Attacker (a contract that holds ETH, has a fallback that calls Put with a second amount). Give the Attacker enough ETH for both Puts. Call Put from Attacker. After the call, assert that Attacker's balance in Acc[attacker] increased by exactly the sum? In reference, it should increase by only the first amount (since reentry is blocked). In mutant, it increases by sum of both amounts.
        // But the property "balanceAfter == balanceBefore + firstAmount" holds for reference only. For mutant, it fails because balanceAfter > balanceBefore + firstAmount.
        // So the test: balanceAfter == balanceBefore + firstAmount is the invariant for reference; mutant breaks it.
        // This matches exactly the required assertion.
        // Implementation details: Attacker contract has a state variable to know when to reenter and the extra amount.
    }
}

