contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 msgeValue, uint256 unlockTime, uint256 reentrancyAttempts) public {
        vm.assume(msgeValue > 0 && msgeValue < 100000 ether);
        vm.assume(reentrancyAttempts > 0 && reentrancyAttempts <= 5);
        LogReentrant maliciousLog = new LogReentrant();
        C corruptible = new C(address(maliciousLog));
        maliciousLog.setTarget(address(corruptible));
        vm.deal(address(this), msgeValue);
        uint256 balanceBefore = address(this).balance - msgeValue;
        vm.prank(address(maliciousLog));
        corruptible.Put{value: msgeValue}(unlockTime);
        vm.prank(address(this));
        bool ok;
        try c.Put{value: msgeValue}(unlockTime) {
            ok = true;
            // In the reference, balance should increase by exactly msgeValue
            // In the mutant, reentrancy could inflate it, but we check the reference contract 'c' here
        } catch {
            ok = false;
        }
        if (ok) {
            uint256 finalBalance = c.Acc(address(this)).balance;
            assertTrue(finalBalance == msgeValue);
        }
    }
}

contract LogReentrant {
    address target;
    uint256 depth;
    function setTarget(address _t) external { target = _t; }
    function AddMessage(address adr, uint256 val, string memory data) public {
        if (depth < 3) {
            depth++;
            (bool success, ) = target.call(abi.encodeWithSignature("Put(uint256)", block.timestamp));
            depth--;
        }
    }
}

