pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 depositAmount, uint256 unlockTime) public {
        // 1. Admissible domain: keep amounts reasonable and avoid overflow in test setup
        vm.assume(amount > 0 && amount <= 1000 ether);
        vm.assume(depositAmount > 0 && depositAmount <= 1000 ether);
        // Ensure the contract can hold the deposit
        vm.assume(depositAmount >= amount);
        // unlockTime can be any uint256, so we don't restrict it.

        // 2. Setup: fund the sender, deploy no adversarial helper because Collect sends ETH to msg.sender and the invariant is about the unlock condition, not about the external call failing.
        address sender = address(0x1234);
        vm.deal(sender, depositAmount);
        vm.startPrank(sender);
        c.Put{value: depositAmount}(unlockTime);
        vm.stopPrank();

        // Warp to an arbitrary time in the future (or past). We don't warp so block.timestamp is whatever the fuzz run decides.
        // The fuzzer controls unlockTime relative to block.timestamp, which is the deciding factor.

        // Attempt the Collect call from the same sender.
        bool success;
        vm.prank(sender);
        try c.Collect(amount) {
            success = true;
        } catch {
            success = false;
        }

        // 3. Assertion: Every successful Collect call must happen when unlockTime < block.timestamp (i.e., funds are unlocked).
        // The reference enforces this; the mutant allows success even when unlockTime >= block.timestamp.
        if (success) {
            (, uint256 bal) = c.Acc(sender);
            // unlockTime is stored in Acc mapping but not directly gettable; we use the fact that the condition block.timestamp > acc.unlockTime must hold.
            // We can infer unlockTime relative to block.timestamp from the call result: if it succeeded, unlockTime < block.timestamp must be true in the reference, but the mutant breaks this.
            // We'll encode the property as: if Collect succeeds, we must have block.timestamp > the stored unlockTime. We can read the unlockTime through the public mapping getter.
            (uint256 unlockTimeStored, ) = c.Acc(sender);
            assertTrue(block.timestamp > unlockTimeStored);
        }
    }
}

