pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 depositAmount, uint256 unlockTimeDelay, uint256 collectAmount) public {
        // Admissible domain: depositAmount and collectAmount must be at least MinSum (1 ether).
        // This ensures the Collect precondition acc.balance >= MinSum && acc.balance >= _am is met.
        vm.assume(depositAmount >= c.MinSum());
        vm.assume(collectAmount >= c.MinSum());
        vm.assume(collectAmount <= depositAmount);

        // unlockTimeDelay must be >0 to ensure a future unlock time.
        vm.assume(unlockTimeDelay > 0);
        vm.assume(unlockTimeDelay <= 365 days);

        // Actor
        address alice = address(0x1000);
        vm.deal(alice, depositAmount);

        // 1. Deposit with a future unlockTime
        uint256 targetUnlock = block.timestamp + unlockTimeDelay;
        vm.prank(alice);
        c.Put{value: depositAmount}(targetUnlock);

        // 2. Assert pre-state: alice is locked (unlock time in the future)
        (, uint256 balBefore, , , , ) = c.Acc(alice);
        assertTrue(block.timestamp < targetUnlock);

        // 3. Collect (the bug allows this even though locked)
        vm.prank(alice);
        bool ok;
        try c.Collect(collectAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // The correct contract MUST revert when locked. The buggy contract may succeed.
        // If the call succeeds on the buggy version, then the balance may drop below MinSum.
        if (ok) {
            (, uint256 balAfter, , , , ) = c.Acc(alice);
            // If the unlock time is still in the future, the balance must remain >= MinSum.
            // The mutant can violate this: it allows Collect while locked, and the balance
            // can drop below MinSum (e.g., if collectAmount > depositAmount - MinSum).
            assertTrue(balAfter >= c.MinSum());
        }
    }
}

